const TRANSITIONS={SCHEDULED:['COUNTDOWN','SCRUBBED'],COUNTDOWN:['HOLD','ASCENT','SCRUBBED'],HOLD:['COUNTDOWN','SCRUBBED'],ASCENT:['SUCCESS','FAILURE'],SUCCESS:['SATELLITE_HANDOFF'],FAILURE:[],SCRUBBED:['SCHEDULED'],SATELLITE_HANDOFF:[]};
export function transitionLaunch(state,next,{evidenceRef}={}){if(!(TRANSITIONS[state]??[]).includes(next))throw new Error(`invalid launch transition ${state} -> ${next}`);if(['ASCENT','SUCCESS','FAILURE','SATELLITE_HANDOFF'].includes(next)&&!evidenceRef)throw new Error('telemetry/evidence required');return{state:next,evidenceRef:evidenceRef??null};}
export function launchTrackProgress(track,{telemetryIndex=null}={}){if(!Array.isArray(track)||!track.length)return{points:[],completed:0};if(!Number.isInteger(telemetryIndex))return{points:[],completed:0,rule:'NO_TELEMETRY_NO_FAKE_PROGRESS'};const idx=Math.max(0,Math.min(track.length-1,telemetryIndex));return{points:track.slice(0,idx+1),completed:(idx+1)/track.length};}
